
public class Every7thNumber {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		//2. 3. using for loops write a Java Program to display every 7th number from 1 to 200
		
		System.out.println("Question number: 3 ");
		for (int iTemp=1;iTemp<=200;iTemp++ ) {
			if(iTemp%7 == 0) {
				System.out.print(iTemp+ " ");
				
			}
			
		}

	}

}
